WITH "authorized_Printing" AS NOT MATERIALIZED (SELECT "root"."id" AS "id" FROM "Printing" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"authorized_Deck" AS NOT MATERIALIZED (SELECT "root"."entity" AS "entity", "root"."id" AS "id", "leaf"."label" AS "label", "root"."name" AS "name", NULL AS "printing.id" FROM "Deck" "leaf" JOIN "Entity" "root" ON "root"."id" = "leaf"."id"),
"batch_selected_rows_0" AS MATERIALIZED ( SELECT "t".* FROM "authorized_Printing" "t"    ),
"batch_selected_roots_1" AS MATERIALIZED ( SELECT "t"."id" AS "id"  FROM "batch_selected_rows_0" "t" ),
"batch_source_2" AS MATERIALIZED (SELECT "cj3"."printing.id" AS "__parent_id", "cj3".* FROM "DeckPrinting" "cj3" JOIN "batch_selected_roots_1" "t" ON TRUE WHERE "cj3"."printing.id" = "t"."id"),
"flat_targets_fb4" AS MATERIALIZED (SELECT "ct1".* FROM "authorized_Deck" "ct1" WHERE "ct1"."id" IN (SELECT "__edge_row"."deck.id" FROM "batch_source_2" AS "__edge_row")),
"flat_base_fb4" AS MATERIALIZED (SELECT "__edge_row"."__parent_id", "ct1"."id" AS "__item_id", "ct1".*, (CASE WHEN (ct1."id" IS NOT DISTINCT FROM $1) THEN TRUE ELSE FALSE END) AS "__batch_filter", (CASE WHEN (ct1."id" IS NOT DISTINCT FROM $2) THEN TRUE ELSE FALSE END) AS "__batch_filter_matched" FROM "batch_source_2" AS "__edge_row" JOIN "flat_targets_fb4" "ct1" ON "ct1"."id" = "__edge_row"."deck.id"),
"flat_flags_fb4" AS MATERIALIZED (SELECT "__parent_id", "__item_id", bool_or("__batch_filter") AS "__batch_filter", bool_or("__batch_filter_matched") AS "__batch_filter_matched" FROM "flat_base_fb4" GROUP BY "__parent_id", "__item_id"),
"flat_unique_fb4" AS MATERIALIZED (SELECT DISTINCT ON ("__parent_id", "__item_id") * FROM "flat_base_fb4" ORDER BY "__parent_id", "__item_id"),
"flat_selected_fb4" AS MATERIALIZED (SELECT u.*, f."__batch_filter" AS "__batch_filter_agg", f."__batch_filter_matched" AS "__batch_filter_matched_agg"  FROM "flat_unique_fb4" u JOIN "flat_flags_fb4" f ON f."__parent_id" = u."__parent_id" AND f."__item_id" = u."__item_id"  WHERE f."__batch_filter" IS TRUE),
"flat_matched_fb4" AS MATERIALIZED (SELECT u.* FROM "flat_unique_fb4" u JOIN "flat_flags_fb4" f ON f."__parent_id" = u."__parent_id" AND f."__item_id" = u."__item_id" WHERE f."__batch_filter_matched" IS TRUE),
"flat_rows_fb4" AS MATERIALIZED (SELECT "fi5"."__parent_id", "fi5"."__item_id", fi5."id" AS "id", fi5."name" AS "name", fi5."entity" AS "entity", fi5."label" AS "label" FROM "flat_selected_fb4" "fi5" ),
"flat_counts_fb4" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_unique_fb4" GROUP BY "__parent_id"),
"flat_items_fb4" AS MATERIALIZED (WITH "__item_group" AS MATERIALIZED (SELECT "__parent_id", COALESCE(json_agg(row_to_json("__item") ORDER BY "__item"."__item_id")  , '[]'::json) AS "__items"  FROM "flat_rows_fb4" AS "__item" GROUP BY "__parent_id") , "__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM "flat_matched_fb4" GROUP BY "__parent_id") SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__matched") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id"),
"flat_base_fr9" AS MATERIALIZED (SELECT "cj8"."printing.id" AS "__parent_id", "cj8"."quantity" AS "quantity", "cj8"."printing.id" AS "printing", "cj8"."deck.id" AS "deck", (CASE WHEN ("cj8"."quantity" IS NOT DISTINCT FROM $3) THEN TRUE ELSE FALSE END) AS "__batch_filter", (CASE WHEN ("cj8"."quantity" IS NOT DISTINCT FROM $4) THEN TRUE ELSE FALSE END) AS "__batch_filter_matched" FROM "DeckPrinting" "cj8" JOIN "batch_selected_roots_1" "t" ON TRUE WHERE "cj8"."printing.id" = "t"."id"),
"flat_selected_fr9" AS MATERIALIZED (SELECT * FROM "flat_base_fr9" WHERE "__batch_filter" IS TRUE),
"flat_matched_fr9" AS MATERIALIZED (SELECT * FROM "flat_base_fr9" WHERE "__batch_filter_matched" IS TRUE),
"flat_counts_fr9" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__total" FROM "flat_base_fr9" GROUP BY "__parent_id"),
"flat_items_fr9" AS MATERIALIZED (WITH "__item_group" AS MATERIALIZED (SELECT "__parent_id", COALESCE(json_agg(json_build_object('quantity', "__item"."quantity") ORDER BY "__item"."printing", "__item"."deck")  , '[]'::json) AS "__items"  FROM "flat_selected_fr9" AS "__item" GROUP BY "__parent_id") , "__matched" AS MATERIALIZED (SELECT "__parent_id", count(*)::int AS "__matched" FROM "flat_matched_fr9" GROUP BY "__parent_id") SELECT "__parents"."__parent_id", COALESCE("__item_group"."__items", '[]'::json) AS "__items", COALESCE("__matched"."__matched", 0) AS "__matched" FROM (SELECT "__parent_id" FROM "__item_group" UNION SELECT "__parent_id" FROM "__matched") AS "__parents" LEFT JOIN "__item_group" ON "__item_group"."__parent_id" = "__parents"."__parent_id" LEFT JOIN "__matched" ON "__matched"."__parent_id" = "__parents"."__parent_id") SELECT t."id" AS "id", COALESCE("bc6"."__items", '[]'::json) AS "decks", COALESCE("bc6"."__matched", 0) AS "decks__matched", COALESCE("bn7"."__total", 0) AS "decks__total", COALESCE("bc10"."__items", '[]'::json) AS "entries", COALESCE("bc10"."__matched", 0) AS "entries__matched", COALESCE("bn11"."__total", 0) AS "entries__total" FROM "batch_selected_rows_0" "t" LEFT JOIN "flat_items_fb4" "bc6" ON "bc6"."__parent_id" = "t"."id" LEFT JOIN "flat_counts_fb4" "bn7" ON "bn7"."__parent_id" = "t"."id" LEFT JOIN "flat_items_fr9" "bc10" ON "bc10"."__parent_id" = "t"."id" LEFT JOIN "flat_counts_fr9" "bn11" ON "bn11"."__parent_id" = "t"."id"  
